INSERT INTO incidents VALUES ('incident-nanjing','南京鼓楼区 · 社区支援','江苏省 南京市 鼓楼区',32.0603,118.7969,'active','2026-10-14T16:20:00Z');
INSERT INTO tasks VALUES ('task-supply','incident-hangzhou','org-demo','安置点物资整理','协助清点、分类及登记生活物资，招募 8 名志愿者。','open','2026-10-15T08:40:00Z','[{"type":"heading","text":"一起做好安置点的后勤支持"},{"type":"paragraph","text":"这是课设演示任务，不对应真实火情。工作范围为安置点物资分类和登记，具体时间及安排在报名通过后由组织者联系确认。"},{"type":"table","rows":[["事项","说明"],["工作地点","杭州 · 西湖区（演示）"],["预计时长","半天"],["装备建议","舒适衣物、饮水"]]},{"type":"map","text":"演示集合区域","latitude":30.2741,"longitude":120.1551},{"type":"paragraph","text":"请根据自身情况报名。申请通过后，将按你的授权开放联系方式。"}]','["realName","region"]','["phone"]');
INSERT INTO tasks VALUES ('task-transport','incident-hangzhou','org-demo','物资运输协助','招募持有有效驾驶资质、可提供车辆的志愿者。','open','2026-10-15T07:30:00Z','[{"type":"heading","text":"把物资送到需要的地方"},{"type":"paragraph","text":"演示任务：协助日用品运输。报名时请提供装备情况和驾驶资质证明，路线及安排由组织者与你直接确认。"}]','["realName","equipment","skills"]','["phone"]');
INSERT INTO tasks VALUES ('task-support','incident-nanjing','org-demo','临时服务点信息登记','协助登记物资需求，为到访居民提供信息指引。','open','2026-10-14T16:20:00Z','[{"type":"heading","text":"耐心倾听，准确记录"},{"type":"paragraph","text":"课设演示任务。协助服务点做好信息登记，具备沟通和基本电子表格使用能力即可报名。"}]','["realName"]','["phone","wechat"]');
INSERT INTO articles VALUES ('article-start','第一次参加志愿服务，从这里开始','完善档案、读懂任务，再做出适合自己的选择。','入门指南',3,'[{"type":"heading","text":"先了解，再报名"},{"type":"paragraph","text":"阅读任务说明，确认工作内容、地点、时间和所需能力。FireLink 帮助你与发布者建立联系，具体安排由双方沟通确认。"},{"type":"heading","text":"准备好你的资料"},{"type":"paragraph","text":"在个人信息中填写常活动的区域、装备和技能证明。报名时逐项选择愿意提供的资料，留意哪些联系方式会在通过后自动开放。"}]');
INSERT INTO articles VALUES ('article-privacy','报名时，我的信息会提供给谁？','了解资料选择、审核结果与联系方式的开放时机。','使用指南',2,'[{"type":"paragraph","text":"你选择的报名资料只供对应任务的组织者审核。联系方式在报名时单独授权，审核通过后自动开放。未通过或撤回的申请不会开放联系方式。"},{"type":"paragraph","text":"个人档案的修改不会自动替换已经提交的申请资料。可以在报名记录中查看提交时的内容和回应。"}]');
